from pathlib import Path
import re
src=Path('/app/benchmark/source_brief.md').read_text()

# Split by headings
sections={}
current=None
buf=[]
for line in src.splitlines():
    m=re.match(r'^(#{1,3})\s+(.*)$', line.strip())
    if m:
        if current:
            sections[current]='\n'.join(buf).strip()+'\n'
        current=m.group(2).strip()
        buf=[]
    else:
        buf.append(line)
if current:
    sections[current]='\n'.join(buf).strip()+'\n'

want=['Nav','Hero','Media Showcase','Client Marquee','About','Founder Letter','Philosophy','Service Details','Clients Grid','Contact Links']
for k in want:
    print('##',k)
    for key in sections:
        if key.lower()==k.lower():
            print(sections[key][:400].strip())
            break
    else:
        # sometimes headings include extra
        match=[key for key in sections if k.lower() in key.lower()]
